// 整理本预设的正文消息。
// 边界位于预设条目中；总结的 generateRaw 请求不包含这些条目。
export const MESSAGE_MARKERS = Object.freeze({
  bodyStart: '<|命定_正文开始|>',
  historyStart: '<|命定_历史开始|>',
  depth900: '<|命定_深度900分界|>',
  depth2: '<|命定_深度2分界|>',
  historyEnd: '<|命定_历史结束|>',
  bodyEnd: '<|命定_正文结束|>',
});
const markerSequence = Object.values(MESSAGE_MARKERS);
const markerIndex = new Map(markerSequence.map((value, index) => [value, index]));
const allMarkers = [...markerIndex.keys()];
const markerPattern = new RegExp(allMarkers.map(value => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|'), 'g');
const markerLabels = ['正文开始', '历史开始', '深度 900', '深度 2', '历史结束', '正文结束'];
export const DISCUSSION_PROTOCOL_VERSION = 1;
export const DISCUSSION_MACRO_MARKER = '<|命定_场外讨论|>';
export const DISCUSSION_CONTEXT = Object.freeze({ start: '<|命定_资料开始|>', end: '<|命定_资料结束|>' });

/** Normalize only the legacy record envelope; quoted examples and media stay intact. */
export function normalizeDiscussionRecord(parts) {
  const first = parts.findIndex(part => part.type === 'text' && String(part.text ?? '').trim());
  if (first < 0 || !/^\s*<destined_discussion>/.test(parts[first].text)) return parts;
  const last = parts.findLastIndex((part, index) => index >= first && part.type === 'text' && part.text.includes('</destined_discussion>'));
  if (last < first) return parts;
  return parts.map((part, index) => {
    if (index !== first && index !== last) return part;
    let text = part.text;
    if (index === first) text = text.replace(/^(\s*)<destined_discussion>/, '$1<discussion_record>');
    if (index === last) {
      const end = text.lastIndexOf('</destined_discussion>');
      text = text.slice(0, end) + '</discussion_record>' + text.slice(end + '</destined_discussion>'.length);
    }
    return { ...part, text };
  });
}

function withoutContextMarkers(parts) {
  return parts.map(part => part.type === 'text' ? { ...part, text: part.text.split(DISCUSSION_CONTEXT.start).join('').split(DISCUSSION_CONTEXT.end).join('') } : part);
}

function contentParts(message) {
  if (typeof message.content === 'string') return [{ type: 'text', text: message.content }];
  return Array.isArray(message.content) ? message.content : [];
}
function isPlainText(part) {
  return part.type === 'text' && typeof part.text === 'string' && Object.keys(part).every(key => key === 'type' || key === 'text');
}
function appendPart(parts, part) {
  if (isPlainText(part) && isPlainText(parts.at(-1) ?? {})) parts.at(-1).text += part.text;
  else parts.push(structuredClone(part));
}
function cleanParts(parts) {
  const result = [];
  for (const part of parts) appendPart(result, part);
  for (const part of result) if (part.type === 'text') part.text = part.text.replace(/\n{3,}/g, '\n\n');
  if (result[0]?.type === 'text') result[0].text = result[0].text.trimStart();
  if (result.at(-1)?.type === 'text') result.at(-1).text = result.at(-1).text.trimEnd();
  return result.filter(part => !isPlainText(part) || part.text !== '');
}
function joinParts(groups) {
  const result = [];
  for (const group of groups) {
    const parts = cleanParts(group);
    if (!parts.length) continue;
    if (result.length) appendPart(result, { type: 'text', text: '\n\n' });
    for (const part of parts) appendPart(result, part);
  }
  return cleanParts(result);
}
function asContent(parts) {
  return parts.every(isPlainText) ? parts.map(part => part.text).join('') : parts;
}
function fragment(bucket, source, index, part) {
  let record = bucket.at(-1);
  if (!record || record.index !== index) bucket.push(record = { source, index, parts: [] });
  appendPart(record.parts, part);
}
function replaceSlot(parts, slot, replacement) {
  let count = 0;
  const result = [];
  for (const part of parts) {
    const text = part.type === 'text' ? part.text : '';
    if (!text.includes(slot)) { appendPart(result, part); continue; }
    const strings = text.split(slot);
    strings.forEach((text, index) => {
      if (index) { count++; for (const inserted of replacement) appendPart(result, inserted); }
      appendPart(result, { ...part, text });
    });
  }
  if (count !== 1) throw new Error(`命定消息处理：${slot} 槽位应出现一次，请恢复对应的结构条目。`);
  return result;
}
function outerMessages(records) {
  return records.flatMap(record => {
    const parts = cleanParts(record.parts);
    return parts.length ? [{ ...structuredClone(record.source), content: asContent(parts) }] : [];
  });
}

function validateDiscussionMacros(messages, mode) {
  const text = messages.flatMap(message => contentParts(message).filter(part => part.type === 'text').map(part => part.text)).join('\n');
  const count = text.split(DISCUSSION_MACRO_MARKER).length - 1;
  const expected = mode === 'discussion' ? 1 : 0;
  const start = text.indexOf(MESSAGE_MARKERS.bodyStart), end = text.lastIndexOf(MESSAGE_MARKERS.bodyEnd);
  const outer = [start < 0 ? text : text.slice(0, start), end < 0 ? '' : text.slice(end + MESSAGE_MARKERS.bodyEnd.length)];
  // Check only template regions: quoted macro examples in chat are ordinary material.
  // Legacy engines may expand getvar but leave the surrounding if block intact.
  const unresolved = outer.some(part => /{{\s*(?:#?if\b[^\n]*|getvar\s*::\s*)ooc_discussion_this_turn/.test(part)
    || (part.includes(DISCUSSION_MACRO_MARKER) && /{{\s*#?if\b/.test(part)));
  const details = `本轮：${mode === 'discussion' ? '讨论' : '剧情'}；讨论标记：${count} 个，预期 ${expected} 个；未展开条件宏：${unresolved ? '有' : '未检出'}`;
  if (unresolved) throw new Error(`Macro điều kiện thảo luận OOC chưa được mở rộng (${details}). Vui lòng vào SillyTavern「Cài đặt người dùng → Xử lý trò chuyện / tin nhắn」bật Experimental Macro Engine và F5 làm mới; nếu không có tùy chọn này vui lòng cập nhật SillyTavern.`);
  if (count === expected) return;
  if (count > 1) throw new Error(`讨论标记重复（${details}）。请检查是否同时启用了多个模型头部或头部副本，以及聊天／自定义条目是否含有内部讨论标记。`);
  if (expected === 1) throw new Error(`缺少讨论标记（${details}）。请检查当前模型头部是否启用并包含讨论分支，恢复配套条目后重试。`);
  throw new Error(`剧情请求中残留讨论标记（${details}）。请确认配套助手正常加载并刷新页面；若仍报错，检查模式状态和聊天／自定义条目中的内部讨论标记。`);
}

/** 返回新的正文请求；没有命定边界时返回 null，不修改任何输入对象。 */
export function processDestinedMessages(messages, { mode = 'story' } = {}) {
  if (!Array.isArray(messages)) return null;
  if (!messages.some(message => contentParts(message).some(part => part.type === 'text' && [...allMarkers, DISCUSSION_MACRO_MARKER, '<|命定_场外原生|>'].some(marker => part.text.includes(marker))))) return null;
  if (messages.some(message => contentParts(message).some(part => part.type === 'text' && part.text.includes('<|命定_场外原生|>')))) throw new Error('收到旧版场外路由标记，请导入配套宏版本预设与助手并刷新页面。');
  validateDiscussionMacros(messages, mode);
  messages = messages.map(message => ({ ...message, content: asContent(contentParts(message).map(part => part.type === 'text' ? { ...part, text: part.text.split(DISCUSSION_MACRO_MARKER).join('') } : part)) }));

  // 七段分别是：头部、历史前正文、>900、3~900、0~2、历史后正文、尾部。
  const sections = Array.from({ length: 7 }, () => []);
  let position = 0;
  messages.forEach((message, index) => {
    for (const part of contentParts(message)) {
      if (part.type !== 'text') { fragment(sections[position], message, index, part); continue; }
      let offset = 0;
      for (const match of part.text.matchAll(markerPattern)) {
        if (match.index > offset) fragment(sections[position], message, index, { ...part, text: part.text.slice(offset, match.index) });
        if (markerIndex.get(match[0]) !== position) throw new Error(`命定消息处理：边界重复或顺序异常，应先出现「${markerLabels[position] ?? '处理结束'}」。`);
        position++;
        offset = match.index + match[0].length;
      }
      if (offset < part.text.length) fragment(sections[position], message, index, { ...part, text: part.text.slice(offset) });
    }
  });
  if (position !== markerSequence.length) throw new Error(`命定消息处理：缺少「${markerLabels[position]}」边界，请检查结构条目是否启用及上下文容量。`);

  const [head, before, high, middle, low, after, tail] = sections;
  const history = [], injections = [];
  for (const section of [high, middle, low]) {
    const system = [];
    for (const record of section) {
      if (record.source.role === 'system') { system.push(record.parts); continue; }
      if (!['user', 'assistant'].includes(record.source.role) || record.source.tool_calls) throw new Error('命定消息处理：正文历史包含不支持的工具消息。');
      const parts = cleanParts(normalizeDiscussionRecord(record.parts.map(part => part.type === 'text'
        ? { ...part, text: part.text.replace(/<\|placeholder\|>/g, '') } : part)));
      if (parts.length) history.push({ ...record, parts });
    }
    injections.push(joinParts(system));
  }
  const latestUser = history.findLast(record => record.source.role === 'user');
  const historyParts = history.map(record => {
    const latest = record === latestUser;
    const prefix = latest ? 'Participant:<Participant_input>\n' : record.source.role === 'user' ? 'Participant: ' : 'Recorder: ';
    return [{ type: 'text', text: prefix }, ...record.parts, ...(latest ? [{ type: 'text', text: '\n</Participant_input>' }] : [])];
  });
  let beforeParts = withoutContextMarkers(joinParts(before.map(record => record.parts)));
  beforeParts = replaceSlot(beforeParts, '<|命定_记忆区|>', injections[0]);
  beforeParts = replaceSlot(beforeParts, '<|命定_参考区|>', injections[1]);
  const afterParts = replaceSlot(joinParts(after.map(record => record.parts)), '<|命定_运行规则区|>', injections[2]);
  const body = asContent(joinParts([beforeParts, ...historyParts, afterParts]));
  return [...outerMessages(head), { role: 'user', content: body }, ...outerMessages(tail)];
}

function hasRecorderPrefill(messages) {
  const assistant = [...messages].reverse().find(message => message?.role === 'assistant');
  if (!assistant || !contentParts(assistant).every(part => part.type === 'text' && typeof part.text === 'string')) return false;
  const content = contentParts(assistant).map(part => part.text).join('');
  return /<recorder_output>\s*<recorder_thinking>\s*$/i.test(content);
}

/** 两种模式共用原消息分区；条目内容由酒馆原生条件宏选择。 */
export function installMessageProcessing({ on, last = on, off, events, active = () => true, assertRequestReady = () => {}, legacyLoaded = () => false, notify = () => {}, afterData = true, requestMode = () => 'story', onPreparedOutput = () => true }) {
  const requests = new WeakMap();
  let disposed = false;
  const enabled = () => !disposed && active();
  const process = (messages, dryRun = false, type) => {
    if (!enabled()) return;
    if (!Array.isArray(messages) || !messages.some(message => contentParts(message).some(part => part.type === 'text' && [...allMarkers, DISCUSSION_MACRO_MARKER, '<|命定_场外原生|>'].some(marker => part.text.includes(marker))))) return;
    try {
      // A preview may be built during preset edits or before the assistant
      // loads. Process the branch actually expanded in that preview without
      // consulting or changing the frozen state of a real generation.
      const previewDiscussion = dryRun && messages.some(message => contentParts(message).some(part => part.type === 'text' && part.text.includes(DISCUSSION_MACRO_MARKER)));
      const mode = dryRun ? (previewDiscussion ? 'discussion' : 'story') : requestMode({ dryRun, type });
      if (!dryRun) assertRequestReady({ dryRun, mode, type });
      const result = processDestinedMessages(messages, { mode });
      if (!result) return;
      if (legacyLoaded()) throw new Error('SPreset脚本仍在此页面运行。如果刚从使用SPreset脚本的其他预设切换至本预设，请刷新一次酒馆；如果当前仍启用了SPreset脚本，请先停用该脚本，再刷新一次酒馆。');
      messages.splice(0, messages.length, ...result);
      if (!dryRun) {
        requests.set(messages, { mode });
        const recorderPrefill = mode === 'discussion' && hasRecorderPrefill(result);
        if (onPreparedOutput({ recorderPrefill }) === false) throw new Error('讨论模式的 Gemini 预填充需要配套助手更新，请更新后刷新页面。');
      }
    } catch (error) {
      if (!dryRun) {
        requests.set(messages, { error });
        notify(error.message);
      }
    }
  };
  const onData = (data, dryRun) => process(data?.prompt, dryRun === true, data?.type);
  const onReady = data => {
    if (!enabled() || !Array.isArray(data?.messages)) return;
    if (!afterData) process(data.messages, false, data.type);
    const request = requests.get(data.messages);
    if (!request) return;
    if (!request.error && data.type === 'quiet') {
      try { assertRequestReady({ dryRun: false, mode: request.mode, type: data.type }); }
      catch (error) { request.error = error; notify(error.message); }
    }
    if (request.error) {
      // 酒馆会捕获事件回调异常；在其 fetch 前的序列化处阻止不完整正文发送。
      Object.defineProperty(data, 'toJSON', { configurable: true, value() { throw request.error; } });
      return;
    }
    // Native preset assistant messages already carry the selected prefill. This field
    // is the connection's additional prefill, not the native prompt entry.
    if (request.mode === 'discussion') data.assistant_prefill = '';
    if (request.mode !== 'discussion') data.stop = [...new Set([...(Array.isArray(data.stop) ? data.stop : []), 'Participant:'])];
  };
  const onPreset = () => { if (!active()) dispose(); };
  function dispose() {
    if (disposed) return;
    disposed = true;
    if (afterData) off(events.GENERATE_AFTER_DATA, onData);
    off(events.CHAT_COMPLETION_SETTINGS_READY, onReady);
    if (events.OAI_PRESET_CHANGED_AFTER) off(events.OAI_PRESET_CHANGED_AFTER, onPreset);
  }
  if (afterData) last(events.GENERATE_AFTER_DATA, onData);
  last(events.CHAT_COMPLETION_SETTINGS_READY, onReady);
  if (events.OAI_PRESET_CHANGED_AFTER) on(events.OAI_PRESET_CHANGED_AFTER, onPreset);
  return { dispose };
}

if (typeof window !== 'undefined' && typeof eventOn === 'function') {
  const host = window.parent, key = '__destinedPrimeMessageProcessor';
  host[key]?.dispose?.();
  const owner = getLoadedPresetName(), frame = window.frameElement;
  const version = typeof getTavernVersion === 'function' ? getTavernVersion().match(/\d+/g)?.map(Number) : null;
  const afterData = !version || version[0] > 1 || version[1] > 13 || (version[1] === 13 && version[2] > 4);
  const instance = installMessageProcessing({
    on: eventOn, last: eventMakeLast, off: eventRemoveListener, events: tavern_events, afterData,
    active: () => frame?.isConnected !== false && getLoadedPresetName() === owner,
    assertRequestReady: options => {
      const bridge = host.__destinedDiscussionV1;
      if (bridge?.assertRequestReady) bridge.assertRequestReady(options);
      else if (options.mode === 'discussion') throw new Error('讨论模式需要支持条件宏的配套助手，请更新后刷新页面。');
    },
    legacyLoaded: () => !!host.SPresetImports?.promptManager,
    notify: message => toastr.error(message, '命定消息处理', { preventDuplicates: true }),
    requestMode: options => host.__destinedDiscussionV1?.requestMode(options) ?? 'story',
    onPreparedOutput: output => {
      const bridge = host.__destinedDiscussionV1;
      const accepted = bridge?.setRequestOutput?.(output) === true;
      return !output.recorderPrefill || accepted;
    },
  });
  const dispose = () => { instance.dispose(); window.removeEventListener('pagehide', dispose); if (host[key]?.dispose === dispose) delete host[key]; };
  host[key] = { dispose, discussionProtocolVersion: DISCUSSION_PROTOCOL_VERSION, discussionSettingsVersion: 6, macroDiscussionVersion: 2 };
  window.addEventListener('pagehide', dispose, { once: true });
}

